// Recorrido en ángulo recto para las líneas del Desktop (linkRouting="orthogonal", B18 de w3f-data-analysis):
// rodea las ventanas en vez de pasar por debajo. Las ventanas (agrandadas en MARGIN) son obstáculos; la grilla son
// sus bordes y las puntas de salida; A* busca el camino con menos largo y menos esquinas (BEND por esquina).
// Sale y llega por el lado que convenga (el enfrentado cuesta menos). Sin camino libre devuelve null (la curva).

import type { LinkGeometry, LinkRect } from './Desktop.links';

const MARGIN = 16;        // distancia mínima entre la línea y una ventana
const BEND = 40;          // costo de cada esquina (en píxeles de largo)
const RADIUS = 10;        // radio de las esquinas redondeadas
const LABEL = 24;         // los rótulos van a esa distancia de la punta, afuera de la ventana
const EDGE_INSET = 12;    // la punta no se acerca a las esquinas de la ventana más que esto

type Side = 0 | 1 | 2 | 3;                                      // derecha, abajo, izquierda, arriba
const NX = [1, 0, -1, 0], NY = [0, 1, 0, -1];

interface Box { l: number; t: number; r: number; b: number; }

const grow = (o: LinkRect, m: number): Box => ({ l: o.left - m, t: o.top - m, r: o.left + o.width + m, b: o.top + o.height + m });
const inside = (x: number, y: number, k: Box) => x > k.l && x < k.r && y > k.t && y < k.b;

/** Punta en el borde `side` de `w`, corrida `offset` a lo largo del borde (sin pasarse de las esquinas). */
function port(w: LinkRect, side: Side, offset: number): [number, number] {
    const clamp = (v: number, lo: number, hi: number) => (lo > hi ? (lo + hi) / 2 : Math.min(hi, Math.max(lo, v)));
    const cx = w.left + w.width / 2, cy = w.top + w.height / 2;
    if (side === 0 || side === 2) {
        const y = clamp(cy + offset, w.top + EDGE_INSET, w.top + w.height - EDGE_INSET);
        return [side === 0 ? w.left + w.width : w.left, y];
    }
    const x = clamp(cx + offset, w.left + EDGE_INSET, w.left + w.width - EDGE_INSET);
    return [x, side === 1 ? w.top + w.height : w.top];
}

/** Costo de salir por `side` hacia el punto (dx, dy): 0 si está enfrente, más si hay que dar la vuelta. */
function sidePenalty(side: Side, dx: number, dy: number): number {
    const len = Math.hypot(dx, dy) || 1;
    return (1 - (NX[side] * dx + NY[side] * dy) / len) * 60;
}

/** Montículo binario mínimo de índices de estado según `f`. */
class Heap {
    private a: number[] = [];
    constructor(private f: Float64Array) {}
    get size() { return this.a.length; }
    push(i: number) {
        const a = this.a, f = this.f;
        a.push(i);
        let c = a.length - 1;
        while (c > 0) {
            const p = (c - 1) >> 1;
            if (f[a[p]] <= f[a[c]]) break;
            [a[p], a[c]] = [a[c], a[p]]; c = p;
        }
    }
    pop(): number {
        const a = this.a, f = this.f, top = a[0], last = a.pop()!;
        if (a.length) {
            a[0] = last;
            let p = 0;
            for (;;) {
                const l = 2 * p + 1, r = l + 1;
                let m = p;
                if (l < a.length && f[a[l]] < f[a[m]]) m = l;
                if (r < a.length && f[a[r]] < f[a[m]]) m = r;
                if (m === p) break;
                [a[p], a[m]] = [a[m], a[p]]; p = m;
            }
        }
        return top;
    }
}

/** Camino con esquinas redondeadas por los puntos (ya sin puntos alineados de más). */
export function roundedPath(pts: [number, number][], radius = RADIUS): string {
    let d = `M ${pts[0][0]} ${pts[0][1]}`;
    for (let i = 1; i < pts.length - 1; i++) {
        const [px, py] = pts[i - 1], [x, y] = pts[i], [nx, ny] = pts[i + 1];
        const r = Math.min(radius, Math.hypot(x - px, y - py) / 2, Math.hypot(nx - x, ny - y) / 2);
        const ax = x - Math.sign(x - px) * r, ay = y - Math.sign(y - py) * r;
        const bx = x + Math.sign(nx - x) * r, by = y + Math.sign(ny - y) * r;
        d += ` L ${ax} ${ay} Q ${x} ${y} ${bx} ${by}`;
    }
    const [lx, ly] = pts[pts.length - 1];
    return `${d} L ${lx} ${ly}`;
}

function simplify(pts: [number, number][]): [number, number][] {
    const out: [number, number][] = [];
    for (const p of pts) {
        if (out.length && out[out.length - 1][0] === p[0] && out[out.length - 1][1] === p[1]) continue;
        while (out.length >= 2) {
            const [ax, ay] = out[out.length - 2], [bx, by] = out[out.length - 1];
            if ((ax === bx && bx === p[0]) || (ay === by && by === p[1])) out.pop(); else break;
        }
        out.push(p);
    }
    return out;
}

/**
 * Recorrido en ángulo recto de `s` a `t` que no pasa por ninguna de `obstacles` (que pueden incluir a `s` y `t`).
 * `offset` corre las puntas a lo largo del borde (líneas que llegan a la misma ventana). null si no hay camino.
 */
export function routeOrthogonal(s: LinkRect, t: LinkRect, obstacles: LinkRect[], offset = 0): LinkGeometry | null {
    const boxes = obstacles.map((o) => grow(o, MARGIN));
    const sCx = s.left + s.width / 2, sCy = s.top + s.height / 2;
    const tCx = t.left + t.width / 2, tCy = t.top + t.height / 2;

    // puntas y sus «stubs» (la punta corrida MARGIN hacia afuera: ahí empieza la grilla)
    const ends = (w: LinkRect, ox: number, oy: number) => ([0, 1, 2, 3] as Side[]).map((side) => {
        const [px, py] = port(w, side, offset);
        return { side, px, py, x: px + NX[side] * MARGIN, y: py + NY[side] * MARGIN, pen: sidePenalty(side, ox, oy) };
    });
    const free = (x: number, y: number) => !boxes.some((k) => inside(x, y, k));
    const starts = ends(s, tCx - sCx, tCy - sCy).filter((e) => free(e.x, e.y));
    const goals = ends(t, sCx - tCx, sCy - tCy).filter((e) => free(e.x, e.y));
    if (!starts.length || !goals.length) return null;

    const uniq = (v: number[]) => Array.from(new Set(v.map((n) => Math.round(n * 100) / 100))).sort((a, b) => a - b);
    const xs = uniq([...boxes.flatMap((k) => [k.l, k.r]), ...starts.map((e) => e.x), ...goals.map((e) => e.x)]);
    const ys = uniq([...boxes.flatMap((k) => [k.t, k.b]), ...starts.map((e) => e.y), ...goals.map((e) => e.y)]);
    const W = xs.length, H = ys.length;
    const xi = new Map(xs.map((v, i) => [v, i])), yi = new Map(ys.map((v, i) => [v, i]));
    const key = (v: number) => Math.round(v * 100) / 100;

    // nodo libre y tramo libre entre nodos vecinos (entre dos líneas de la grilla no hay bordes: basta el medio)
    const nodeFree = new Uint8Array(W * H);
    for (let j = 0; j < H; j++) for (let i = 0; i < W; i++) nodeFree[j * W + i] = free(xs[i], ys[j]) ? 1 : 0;

    const N = W * H * 4;                                    // estado = nodo × dirección de llegada
    const g = new Float64Array(N).fill(Infinity), f = new Float64Array(N).fill(Infinity);
    const prev = new Int32Array(N).fill(-1);
    const goalAt = new Map<number, { side: Side }>();
    for (const e of goals) goalAt.set(yi.get(key(e.y))! * W + xi.get(key(e.x))!, { side: e.side });
    const h = (i: number, j: number) => Math.min(...goals.map((e) => Math.abs(xs[i] - e.x) + Math.abs(ys[j] - e.y)));

    const heap = new Heap(f);
    for (const e of starts) {
        const n = yi.get(key(e.y))! * W + xi.get(key(e.x))!;
        const st = n * 4 + e.side;
        if (e.pen < g[st]) { g[st] = e.pen; f[st] = e.pen + h(n % W, (n / W) | 0); prev[st] = -1 - starts.indexOf(e); heap.push(st); }
    }

    let found = -1;
    const closed = new Uint8Array(N);
    while (heap.size) {
        const st = heap.pop();
        if (closed[st]) continue;
        closed[st] = 1;
        const n = st >> 2, dir = st & 3, i = n % W, j = (n / W) | 0;
        const goal = goalAt.get(n);
        // llegar entrando de frente al lado elegido (dirección = hacia adentro = opuesta a la normal)
        if (goal && dir === ((goal.side + 2) & 3)) { found = st; break; }
        for (let nd = 0; nd < 4; nd++) {
            if (nd === ((dir + 2) & 3)) continue;           // no volver por donde vino
            const ni = i + NX[nd], nj = j + NY[nd];
            if (ni < 0 || nj < 0 || ni >= W || nj >= H) {
                continue;
            }
            const nn = nj * W + ni;
            if (!nodeFree[nn]) continue;
            const mx = (xs[i] + xs[ni]) / 2, my = (ys[j] + ys[nj]) / 2;
            if (!free(mx, my)) continue;
            const ns = nn * 4 + nd;
            const cost = g[st] + Math.abs(xs[ni] - xs[i]) + Math.abs(ys[nj] - ys[j]) + (nd === dir ? 0 : BEND);
            if (cost < g[ns]) {
                g[ns] = cost; f[ns] = cost + h(ni, nj); prev[ns] = st; heap.push(ns);
            }
        }
        // en el stub de llegada se puede doblar para entrar de frente
        if (goal && dir !== ((goal.side + 2) & 3)) {
            const ns = n * 4 + ((goal.side + 2) & 3);
            const cost = g[st] + BEND;
            if (cost < g[ns]) { g[ns] = cost; f[ns] = cost; prev[ns] = st; heap.push(ns); }
        }
    }
    if (found < 0) return null;

    // de atrás para adelante
    const pts: [number, number][] = [];
    let st = found, startIdx = 0;
    while (st >= 0) {
        const n = st >> 2;
        pts.push([xs[n % W], ys[(n / W) | 0]]);
        const p = prev[st];
        if (p < 0) { startIdx = -1 - p; break; }
        st = p;
    }
    pts.reverse();
    const a = starts[startIdx];
    const z = goals.find((e) => e.x === pts[pts.length - 1][0] && e.y === pts[pts.length - 1][1])
        ?? goals.reduce((m, e) => (Math.hypot(e.x - pts[pts.length - 1][0], e.y - pts[pts.length - 1][1])
            < Math.hypot(m.x - pts[pts.length - 1][0], m.y - pts[pts.length - 1][1]) ? e : m));
    const all = simplify([[a.px, a.py], ...pts, [z.px, z.py]]);
    return {
        d: roundedPath(all),
        x1: a.px, y1: a.py, x2: z.px, y2: z.py,
        sx: a.px + NX[a.side] * LABEL, sy: a.py + NY[a.side] * LABEL,
        tx: z.px + NX[z.side] * LABEL, ty: z.py + NY[z.side] * LABEL,
    };
}
